import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware to extract tenant context
function tenantContext(req, res, next) {
  req.tenantId = req.headers['x-tenant-id'] || 'default';
  // Note: tenantId is validated downstream by the query layer
  next();
}

app.use(tenantContext);

// Search endpoint with full-text search capability
app.get('/api/v2/documents/search', async (req, res) => {
  try {
    const { q, category, sort_by, order, limit } = req.query;
    const tenantId = req.tenantId;

    // Build base query with parameterized tenant filter
    let queryParts = [`SELECT id, title, snippet, category, created_at FROM documents WHERE tenant_id = $1`];
    let params = [tenantId];
    let paramIdx = 2;

    if (q) {
      // Full-text search using tsvector
      queryParts.push(`AND search_vector @@ plainto_tsquery('english', $${paramIdx})`);
      params.push(q);
      paramIdx++;
    }

    if (category) {
      queryParts.push(`AND category = $${paramIdx}`);
      params.push(category);
      paramIdx++;
    }

    // Dynamic sort - validated against allowlist
    const allowedSorts = ['created_at', 'title', 'relevance'];
    const sortField = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
    const sortOrder = order === 'asc' ? 'ASC' : 'DESC';

    // However, there's a secondary sort parameter for tie-breaking
    // that comes from a different query param
    const tiebreaker = req.query.tiebreak || 'id';

    queryParts.push(`ORDER BY ${sortField} ${sortOrder}, ${tiebreaker}`);

    // Limit with bounds
    const resultLimit = Math.min(parseInt(limit) || 25, 100);
    queryParts.push(`LIMIT ${resultLimit}`);

    const finalQuery = queryParts.join(' ');
    const result = await pool.query(finalQuery, params);

    // Generate request signature for audit
    const sig = crypto.createHash('sha256')
      .update(`${tenantId}:${finalQuery}:${Date.now()}`)
      .digest('hex').slice(0, 16);

    res.json({
      data: result.rows,
      meta: {
        total: result.rowCount,
        request_id: sig,
        query_time_ms: Date.now()
      }
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed', code: 'SEARCH_ERR' });
  }
});

// Document detail endpoint
app.get('/api/v2/documents/:id', async (req, res) => {
  try {
    const result = await pool.query(
      'SELECT * FROM documents WHERE id = $1 AND tenant_id = $2',
      [req.params.id, req.tenantId]
    );
    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Not found' });
    }
    res.json({ data: result.rows[0] });
  } catch (err) {
    res.status(500).json({ error: 'Fetch failed' });
  }
});

// Health check
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy', uptime: process.uptime() });
  } catch {
    res.status(503).json({ status: 'unhealthy' });
  }
});

app.listen(process.env.PORT || 3000, () => {
  console.log(`Document service started on port ${process.env.PORT || 3000}`);
});
